"use client";
// A Lustre island that can be hidden: the ticker's timer keeps firing after the island unmounts,
// but the stopped app takes none of its messages.
import { useState } from "denext";
import { lustreIsland } from "denext/gleam";
// fallow-ignore-next-line unresolved-import -- generated by the gleam() plugin at dev/build (git-ignored)
import { lustre } from "../.denext/lustre.ts";
import * as ticker from "@gleam/app/ticker.mjs";

const Ticker = lustreIsland(lustre, ticker.app(), {
  flags: (props: { every: number }) => props.every,
  attributes: () => ({ class: "ticker-island" }),
});

export function TickerPanel({ every }: { every: number }) {
  const [shown, setShown] = useState(true);
  return (
    <div>
      <button type="button" className="toggle-ticker" onClick={() => setShown(!shown)}>
        {shown ? "Hide" : "Show"} the ticker
      </button>
      {shown && <Ticker every={every} />}
    </div>
  );
}
